-- PostGIS columns the spatial queries read (mirrors migrations 021 and 022).
UPDATE pois
SET boundary_geom = ST_Multi(ST_SetSRID(ST_GeomFromGeoJSON(geometry::text), 4326)),
    geom = ST_SetSRID(ST_MakePoint(longitude, latitude), 4326)
WHERE name = 'Wood Hollow Metro Park' AND boundary_geom IS NULL;

